function stickerDraw(item,selected=false){const x=item.x*W,y=item.y*H,s=item.size||60;ctx.save();ctx.translate(x,y);ctx.rotate(item.rot||0);ctx.textAlign='center';ctx.textBaseline='middle';ctx.font=`${s}px "Apple Color Emoji","Segoe UI Emoji","Noto Color Emoji",sans-serif`;
