function sync(){localStorage.setItem('little-cozy-room',JSON.stringify(placed));document.querySelector('#score').textContent=placed.length*10;document.querySelector('#count').textContent=`${placed.length} placed`;document.querySelector('#hint').style.display=placed.length?'none':'block';const n=placed.length;document.querySelector('#mission-title').textContent=n>=5?'Cozy corner complete!':'Make it feel like home';document.querySelector('#mission-text').textContent=n>=5?'Lovely! Your room is full of little things that make it yours.':`Place ${5-n} more little ${5-n===1?'thing':'things'} in your room to finish your cozy corner.`;draw();if(n>=5&&!completed){completed=true;document.querySelector('#success').classList.add('open')}}
function renderStickers(){const grid=document.querySelector('#stickers');grid.innerHTML='';catalog.filter(s=>tab==='all'||s.cat===tab).forEach(item=>{const el=document.createElement('button');el.className='sticker';el.innerHTML=`<span class="emoji">${item.emoji}</span><small>${item.name}</small>`;el.title=`Drag ${item.name} into your room`;el.addEventListener('pointerdown',e=>{e.preventDefault();dragItem=item;pointerStart={x:-100,y:-100};el.setPointerCapture?.(e.pointerId)});el.addEventListener('pointermove',e=>{if(!dragItem)return;pointerStart={x:e.clientX,y:e.clientY};draw()});el.addEventListener('pointerup',e=>{if(!dragItem)return;const r=canvas.getBoundingClientRect();if(e.clientX>=r.left&&e.clientX<=r.right&&e.clientY>=r.top&&e.clientY<=r.bottom){addSticker(item,(e.clientX-r.left)/r.width,(e.clientY-r.top)/r.height)}dragItem=null;pointerStart=null;draw()});el.addEventListener('pointercancel',()=>{dragItem=null;pointerStart=null;draw()});grid.append(el)})}
function addSticker(item,x,y){undoStack.push(JSON.stringify(placed));placed.push({emoji:item.emoji,name:item.name,cat:item.cat,size:item.size,x:Math.max(.05,Math.min(.95,x)),y:Math.max(.12,Math.min(.94,y)),rot:(Math.random()-.5)*.12});active=placed.length-1;sync();toast('So cozy! +10 ✨');playNote()}
function toast(msg){const t=document.querySelector('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),1400)}
function playNote(){if(!soundOn)return;try{const a=new AudioContext(),o=a.createOscillator(),g=a.createGain();o.type='sine';o.frequency.value=660;g.gain.setValueAtTime(.055,a.currentTime);g.gain.exponentialRampToValueAtTime(.001,a.currentTime+.18);o.connect(g);g.connect(a.destination);o.start();o.stop(a.currentTime+.18);o.onended=()=>a.close()}catch(e){}}
function canvasPoint(e){const r=canvas.getBoundingClientRect();return{x:(e.clientX-r.left)/r.width,y:(e.clientY-r.top)/r.height}}
canvas.addEventListener('pointerdown',e=>{const p=canvasPoint(e),x=p.x*W,y=p.y*H;for(let i=placed.length-1;i>=0;i--){const a=placed[i],s=a.size||60;if(Math.hypot(x-a.x*W,y-a.y*H)<s*.8){active=i;pointerStart=p;canvas.setPointerCapture(e.pointerId);draw();return}}active=-1;draw()});
canvas.addEventListener('pointermove',e=>{if(active<0||!pointerStart||!canvas.hasPointerCapture(e.pointerId))return;const p=canvasPoint(e),a=placed[active];a.x=Math.max(.04,Math.min(.96,p.x));a.y=Math.max(.1,Math.min(.96,p.y));pointerStart=p;draw()});
canvas.addEventListener('pointerup',e=>{if(active>=0&&canvas.hasPointerCapture(e.pointerId)){canvas.releasePointerCapture(e.pointerId);pointerStart=null;sync()}});canvas.addEventListener('pointercancel',()=>{pointerStart=null});
document.querySelector('#tabs').addEventListener('click',e=>{const b=e.target.closest('.tab');if(!b)return;document.querySelectorAll('.tab').forEach(t=>t.classList.toggle('active',t===b));tab=b.dataset.tab;renderStickers()});
document.querySelector('#rotate').onclick=()=>{if(active<0){toast('Choose a sticker to rotate');return}placed[active].rot=(placed[active].rot||0)+Math.PI/6;sync()};
document.querySelector('#undo').onclick=()=>{if(undoStack.length){placed=JSON.parse(undoStack.pop());active=placed.length-1;completed=false;document.querySelector('#success').classList.remove('open');sync()}else if(placed.length){placed.pop();active=placed.length-1;completed=false;document.querySelector('#success').classList.remove('open');sync()}else toast('Nothing to undo yet')};
document.querySelector('#reset').onclick=()=>{placed=[];undoStack=[];active=-1;completed=false;document.querySelector('#success').classList.remove('open');sync();toast('A fresh little room ♡')};
document.querySelector('#save').onclick=()=>{try{localStorage.setItem('little-cozy-room',JSON.stringify(placed));toast('Room saved for later ♡')}catch(e){toast('Could not save room')}};
document.querySelector('#sound').onclick=e=>{soundOn=!soundOn;e.currentTarget.textContent=soundOn?'♫':'♪';toast(soundOn?'Sound on':'Sound off')};document.querySelector('#keep').onclick=()=>document.querySelector('#success').classList.remove('open');
renderStickers();sync();new ResizeObserver(resize).observe(canvas.parentElement);resize();

